import chalk from 'chalk';
import { localDiff } from '../core/local-diff.js';
import { computeDiff } from '../core/file-diff.js';
import { createPager } from '../utils/pager.js';
import { displayPath, toModulePath } from '../core/workdir.js';

export function registerDiff(program) {
  program
    .command('diff [file]')
    .description('Show line-by-line diff between working directory and local snapshot (offline)')
    .action(async (targetFile) => {
      const diff = localDiff();

      const allChanged = [
        ...diff.modified.map((f) => ({ ...f, kind: 'modified' })),
        ...diff.newLocal.map((f) => ({ ...f, kind: 'new', remoteContent: '' })),
        ...diff.remoteOnly.map((f) => ({ ...f, kind: 'deleted', localContent: '' })),
      ];

      // Accepts a module path or the on-disk path, with or without `.js`.
      const target = targetFile ? toModulePath(targetFile) : null;
      const filtered = target
        ? allChanged.filter((f) => f.path === target || f.path === `${target}.js`)
        : allChanged;

      // Collect patches first: no pager for empty output.
      const chunks = [];
      for (const f of filtered) {
        const patch = computeDiff(f.remoteContent || '', f.localContent || '', displayPath(f.path));
        if (patch) chunks.push(formatPatch(patch));
      }

      if (!chunks.length) {
        console.log('No changes.');
        return;
      }

      const pager = createPager();
      try {
        for (const chunk of chunks) {
          pager.write(chunk);
          if (!chunk.endsWith('\n')) pager.write('\n');
        }
      } finally {
        await pager.close();
      }
    });
}

function formatPatch(patch) {
  return patch
    .split('\n')
    .map((line) => {
      if (line.startsWith('+') && !line.startsWith('+++')) return chalk.green(line);
      if (line.startsWith('-') && !line.startsWith('---')) return chalk.red(line);
      if (line.startsWith('@@')) return chalk.cyan(line);
      return line;
    })
    .join('\n');
}
